// «→ חזרה» — только видимый с точным текстом: скрытый экран настроек держит «→ חזרה להגדרות».
import { test, expect } from '@playwright/test';
import { DOCS, PARENT_B, backButton, expectDocOpen, visibleText } from './legal-docs.helpers';

test.use({ storageState: PARENT_B });

test.describe('Юридические документы — родитель под входом', () => {
  test('«→ חזרה» с условий, открытых из /privacy, возвращает на /privacy @desktop @prod-safe #d7fe2c', async ({ page }) => {
    await page.goto('/privacy');
    await visibleText(page, 'תנאי השימוש').click();
    await page.waitForURL(DOCS.terms.urlRe);
    await expectDocOpen(page, 'terms');

    await backButton(page).click();
    await page.waitForURL(/\/privacy$/);
    await expect(visibleText(page, 'תנאי השימוש')).toBeVisible();
  });

  test('«→ חזרה» с условий, открытых прямой ссылкой, ведёт в /settings @desktop @prod-safe #d7fe2c', async ({ page }) => {
    await page.goto(DOCS.terms.url);
    await expectDocOpen(page, 'terms');

    // Комментарий 01.11: «'חזרה' מחזיר להגדרות»
    await backButton(page).click();
    await page.waitForURL(/\/settings$/);
    await expect(visibleText(page, 'מדיניות פרטיות ותנאי שימוש')).toBeVisible();
  });
});
